from bioblend.galaxy import GalaxyInstance

api_key = "[REDACTED_GALAXY_API_KEY]"
gi = GalaxyInstance("https://usegalaxy.org", key=api_key)

history_id = "bbd44e69cb8906b56417cac1b3ee29c7"

# Build the tool inputs for DESeq2
# In bioblend, repeats are represented as lists of dicts
inputs = {
    "select_data": {
        "how": "datasets_per_level",
        "rep_factorName": [
            {
                "factorName": "treatment",
                "rep_factorLevel": [
                    {
                        "factorLevel": "DMSO",
                        "countsFile": {"src": "hda", "id": "f9cad7b01a472135f80b2717a4dc4bdb"}
                    },
                    {
                        "factorLevel": "CBD_IC50",
                        "countsFile": {"src": "hda", "id": "f9cad7b01a472135e58b09debb954687"}
                    }
                ]
            }
        ]
    },
    "header": True,
    "tximport": {"tximport_selector": "count"},
    "output_options": {"output_selector": "pdf"}
}

tool_id = "toolshed.g2.bx.psu.edu/repos/iuc/deseq2/deseq2/2.11.40.8+galaxy3"

print("Submitting DESeq2 via BioBlend...")
try:
    result = gi.tools.run_tool(history_id, tool_id, inputs)
    print(f"Result: {json.dumps(result, indent=2)}")
except Exception as e:
    print(f"Error: {e}")
