python3 << 'PYEOF'
import bioblend.galaxy
import json

api_key = "[REDACTED_GALAXY_API_KEY]"
gi = bioblend.galaxy.GalaxyInstance("https://usegalaxy.org", key=api_key)
history_id = "bbd44e69cb8906b56417cac1b3ee29c7"

# First, rename the cut datasets to give them distinct names for DESeq2
for ds_id, new_name in [
    ("f9cad7b01a472135f80b2717a4dc4bdb", "DMSO_counts.tabular"),
    ("f9cad7b01a472135e58b09debb954687", "CBD_IC50_counts.tabular")
]:
    gi.histories.update_dataset(history_id, ds_id, name=new_name)
    print(f"Renamed {ds_id} to {new_name}")

# Now submit DESeq2 with BioBlend using proper nested dict format
# The key issue might be that Galaxy's tool API expects the repeat structure differently
# Let's try the BioBlend-recommended format: 21.01 with nested objects

inputs = {
    "select_data": {
        "how": "datasets_per_level",
        "rep_factorName": [
            {
                "factorName": "treatment",
                "rep_factorLevel": [
                    {
                        "factorLevel": "DMSO",
                        "countsFile": {
                            "src": "hda",
                            "id": "f9cad7b01a472135f80b2717a4dc4bdb"
                        }
                    },
                    {
                        "factorLevel": "CBD_IC50",
                        "countsFile": {
                            "src": "hda",
                            "id": "f9cad7b01a472135e58b09debb954687"
                        }
                    }
                ]
            }
        ]
    },
    "header": True,
    "tximport": {"tximport_selector": "count"},
    "output_options": {"output_selector": "pdf"}
}

tool_id = "toolshed.g2.bx.psu.edu/repos/iuc/deseq2/deseq2/2.11.40.8+galaxy3"

print("\nSubmitting DESeq2 via BioBlend (try 2)...")
result = gi.tools.run_tool(history_id, tool_id, inputs)
job_id = result['jobs'][0]['id']
print(f"Job ID: {job_id}")

# Save job info for monitoring
with open('/workspace/deseq2_job.json', 'w') as f:
    json.dump({'job_id': job_id, 'outputs': result['outputs']}, f)
PYEOF

